	tx_priv->stream_pending[dai->id] = 0;
	if (mute) {
		for_each_set_bit(decimator, &tx_priv->stream_owned[dai->id], NUM_DECIMATORS) {
			reg = LPASS_CDC_TX0_TX_PATH_CTL +
				LPASS_CDC_TX_MACRO_TX_PATH_OFFSET * decimator;
