		ret = regmap_read(regmap, LPASS_CDC_TX_CLK_RST_CTRL_MCLK_CONTROL, &old_mclk);
		if (ret)
			goto rollback_clock;
		ret = regmap_read(regmap, LPASS_CDC_TX_CLK_RST_CTRL_FS_CNT_CONTROL, &old_fs);
		if (ret)
			goto rollback_clock;
