			ret = regmap_update_bits(regmap,
						 LPASS_CDC_TX_CLK_RST_CTRL_MCLK_CONTROL, 1, 1);
			if (!ret)
				ret = regmap_update_bits(regmap,
							 LPASS_CDC_TX_CLK_RST_CTRL_FS_CNT_CONTROL,
							 1, 1);
		} else {
			ret = regmap_update_bits(regmap,
						 LPASS_CDC_TX_CLK_RST_CTRL_FS_CNT_CONTROL, 1, 0);
			if (!ret)
				ret = regmap_update_bits(regmap,
							 LPASS_CDC_TX_CLK_RST_CTRL_MCLK_CONTROL, 1,
							 0);
