		ret = lpass_cdc_clk_rsc_request_clock(tx_priv->dev, TX_CORE_CLK,
						      TX_CORE_CLK, false);
		if (ret) {
			lpass_cdc_clk_rsc_fs_gen_request(tx_priv->dev, true);
			if (tx_priv->tx_mclk_users == 1)
				goto rollback_regs;
			goto vote;
		}
