			tx_priv->failed_clock_owned = true;
			dev_err(tx_priv->dev, "TX clock rollback failed: %d\n", cleanup);
		}
	}
vote:
	if (voted) {
		pm_runtime_mark_last_busy(tx_priv->dev);
		pm_runtime_put_autosuspend(tx_priv->dev);
	}
out:
	mutex_unlock(&tx_priv->mclk_lock);
	return ret;
}

